#pragma once

#include <deki/Component.h>

/**
 * @brief Base class for components with lifecycle methods
 *
 * Behaviour extends Component with:
 * - Lifecycle methods: Awake(), Start(), Update()
 * - Update() is only called on behaviours that DECLARE it (DeclaresUpdate(),
 *   generated by the reflection codegen). A behaviour without an Update
 *   member costs nothing per frame.
 *
 * Lifecycle order:
 * 1. InternalAwake (engine) - Resolves AssetRefs and ObjectRefs
 * 2. Awake() - Component initialization, called once after refs are resolved
 * 3. Start() - Called once before first Update, after ALL Awake calls complete
 * 4. Update() - Called every frame
 * 5. Render (handled by RendererComponent)
 *
 * Use Component for data-only components.
 * Use Behaviour for components that need engine processing.
 */

namespace Deki
{

class Behaviour : public Component
{
public:
    Behaviour()
        : m_HasAwoken(false), m_HasStarted(false)
    {
    }

    virtual ~Behaviour() = default;

    Behaviour* AsBehaviour() override { return this; }

    /**
     * @brief Called once after AssetRefs and ObjectRefs are resolved
     *
     * Use for component self-initialization. All asset references are
     * available at this point.
     */
    virtual void Awake() {}

    /**
     * @brief Called once before first Update, after ALL Awake calls complete
     *
     * Use for cross-component setup. Safe to access other components
     * since all components have been awakened.
     */
    virtual void Start() {}

    /**
     * @brief Called every frame (only if needs_update is true)
     */
    virtual void Update() {}

    // Lifecycle state checks
    bool HasAwoken() const { return m_HasAwoken; }
    bool HasStarted() const { return m_HasStarted; }
    void MarkAwoken() { m_HasAwoken = true; }
    void MarkStarted() { m_HasStarted = true; }

private:
    bool m_HasAwoken;
    bool m_HasStarted;
};

}  // namespace Deki
